(() => {
  'use strict';
  const C = window.VETAS, CFG = window.VETAS_CONFIG;
  const $ = s => document.querySelector(s);
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clamp = (n,max) => Math.max(0,Math.min(max,Number.isInteger(n)?n:0));
  const initial = () => ({page:0,visited:[0],level:'D',tax:0,tray:0,cards:Array(18).fill(''),classReviewed:false,assisted:[],quiz:{},qIndex:{},hints:{},team:'',reason:'',transfer:'',note:''});
  let state = initial(), persistent = true;
  try {
    const saved = JSON.parse(localStorage.getItem(CFG.storageKey) || 'null');
    if(saved && Array.isArray(saved.cards) && saved.cards.length===18) {
      state = {...state,...saved};
      state.page=clamp(state.page,13); state.tray=clamp(state.tray,2);state.tax=clamp(state.tax,4);
      state.visited=Array.isArray(state.visited)?state.visited.filter(n=>Number.isInteger(n)&&n>=0&&n<14):[0];
      state.assisted=Array.isArray(state.assisted)?state.assisted.filter(n=>['coherence','classification','transfer'].includes(n)):[];
      state.cards=state.cards.map(v=>['D','M','C','?'].includes(v)?v:'');
      state.level=['D','M','C'].includes(state.level)?state.level:'D';
      ['team','reason','transfer','note'].forEach(k=>state[k]=typeof state[k]==='string'?state[k].slice(0,10000):'');
      ['quiz','qIndex','hints'].forEach(k=>state[k]=state[k]&&typeof state[k]==='object'&&!Array.isArray(state[k])?state[k]:{});
    }
  } catch { persistent=false; }
  function save(){try{localStorage.setItem(CFG.storageKey,JSON.stringify(state));}catch{persistent=false;}}
  const lockNames={coherence:'Coherencia',classification:'Clasificación',transfer:'Transferencia'};
  const lockIcon='<svg viewBox="0 0 40 40" aria-hidden="true"><path d="M13 18v-6a7 7 0 0 1 14 0v6M10 18h20v17H10zM20 24v5"/></svg>';
  const crystal='<svg viewBox="0 0 100 130" aria-hidden="true"><path d="M50 3 84 34 91 94 50 126 9 94 16 34zM50 3v123M16 34l34 20 34-20M9 94l41-40 41 40M50 126 9 94M50 126l41-32"/></svg>';
  const cite=(...ids)=>`<div class="source-line">${ids.map(id=>`<button class="text-button" data-action="source" data-id="${id}">${esc(C.sources[id].short)} ↗</button>`).join('')}</div>`;
  const head=(tag,title,lead='')=>`<div class="section-title"><div><span class="eyebrow">${tag}</span><h2 tabindex="-1" id="scene-title">${title}</h2></div><span class="time-label">${C.pages[state.page].time} min · en vivo</span></div>${lead?`<p class="lead">${lead}</p>`:''}`;
  const field=(key,label,placeholder='')=>`<label class="field">${label}<textarea data-field="${key}" placeholder="${esc(placeholder)}">${esc(state[key])}</textarea></label>`;
  function qState(group,i){
    state.quiz[group] ||= [];
    let q=state.quiz[group][i];
    if(!q || typeof q!=='object' || !Number.isInteger(q.selected) || q.selected<0 || q.selected>=C.quizzes[group][i].options.length)q={selected:null,checked:null};
    state.quiz[group][i]=q;return q;
  }
  function done(group){return C.quizzes[group].every((q,i)=>qState(group,i).checked===q.answer);}
  function reviewed(group){return C.quizzes[group].filter((q,i)=>qState(group,i).checked!==null).length;}
  function sealStatus(id){
    const solved=id==='coherence'?done('case'):id==='transfer'?done('bridge'):state.classReviewed&&C.cards.every(c=>state.cards[c.id]===c.answer);
    return solved?'solved':state.assisted.includes(id)?'assisted':'locked';
  }
  const sealTexts={
    coherence:['Una cadena con sentido','Objetivo → acción → componente → evidencia. Si un elemento no ayuda a actuar ni a observar el aprendizaje, revisa su presencia.'],
    classification:['Una pauta para la duda','Define la unidad de análisis. Distingue la experiencia global, la regla o proceso y su representación concreta. Justifica con el contexto, no solo con el nombre.'],
    transfer:['Una elección informada','DMC pregunta por el nivel del diseño; Toda por la función del elemento. Combina las lentes para justificar una selección, sin forzar equivalencias ni prometer efectos automáticos.']
  };
  function seal(id){const status=sealStatus(id);return `<aside class="lock-panel ${status!=='locked'?'open':''}"><div class="lock-glyph">${status==='locked'?lockIcon:crystal}</div><div class="lock-meta"><span class="eyebrow">Veta de práctica · ${esc(lockNames[id])}</span><h3>${status==='solved'?'Veta descubierta':status==='assisted'?'Apertura acompañada':'Pauta bajo candado'}</h3></div><p>${status==='locked'?'Resuelve el reto para abrir una pauta extra. También puedes pedir una apertura acompañada.':status==='solved'?'Tus decisiones revisadas permiten abrir la pauta complementaria.':'Has abierto la pauta con apoyo. Puedes volver al reto y revisar tus decisiones.'}</p><button class="button secondary small" data-action="${status==='locked'?'assist':'seal'}" data-id="${id}">${status==='locked'?'Abrir con acompañamiento':'Leer la pauta'}</button><small class="note">Este candado no bloquea la clase.</small></aside>`;}
  function quiz(group){
    const list=C.quizzes[group],i=clamp(state.qIndex[group],list.length-1);state.qIndex[group]=i;
    const q=list[i],s=qState(group,i),correct=s.checked===q.answer;
    return `<div class="quiz-box" data-quiz="${group}"><div class="quiz-meta"><span>Decisión ${i+1} de ${list.length}</span><span>${reviewed(group)} revisadas</span></div><h3 id="question-${group}" tabindex="-1">${esc(q.q)}</h3><div class="options" role="group" aria-label="Opciones de respuesta">${q.options.map((v,j)=>`<button class="choice ${s.selected===j?'selected':''}" aria-pressed="${s.selected===j}" data-action="choose" data-group="${group}" data-index="${j}"><span class="choice-mark" aria-hidden="true">${String.fromCharCode(65+j)}</span><span>${esc(v)}</span></button>`).join('')}</div><div class="actions"><button class="button small" data-action="check" data-group="${group}" ${s.selected===null?'disabled':''}>Contrastar mi decisión</button><button class="text-button" data-action="hint" data-group="${group}">Una pista</button></div>${state.hints[group+'-'+i]?`<div class="feedback hint">${esc(q.hint)}</div>`:''}${s.checked!==null?`<div class="feedback ${correct?'':'error'}" role="status"><strong>${correct?'Decisión fundamentada.':'Volvamos a mirar.'}</strong> ${esc(q.why)}${correct?'':' Puedes elegir otra opción y contrastarla.'}</div>`:''}${list.length>1?`<div class="quiz-navigation"><button class="text-button" data-action="quiz-prev" data-group="${group}" ${i===0?'disabled':''}>← Decisión anterior</button><button class="text-button" data-action="quiz-next" data-group="${group}" ${i===list.length-1?'disabled':''}>Siguiente decisión →</button></div>`:''}</div>`;
  }
  function pyramid(){const l=C.levels[state.level];return `<div class="split pyramid-split"><div class="pyramid" aria-label="Pirámide de tres niveles"><span class="pyramid-direction">Más abstracto</span>${['D','M','C'].map((k,i)=>`<button class="pyramid-level level-${k} ${state.level===k?'active':''}" aria-pressed="${state.level===k}" data-action="level" data-id="${k}"><span class="level-number">0${i+1}</span><strong>${C.levels[k].name}</strong></button>`).join('')}<span class="pyramid-direction bottom">Más concreto</span></div><div class="layer-detail panel"><span class="eyebrow">${esc(l.name)}</span><h3 id="layer-heading" tabindex="-1">${esc(l.question)}</h3><p>${esc(l.definition)}</p><div class="example"><small>EJEMPLO PROPIO</small><p>${esc(l.example)}</p></div><p class="note">Los niveles se articulan. Una misma palabra puede describir objetos distintos según el contexto.</p></div></div>`;}
  function concept(k,heading,lead){const l=C.levels[k],main=k==='D'?l.terms:k==='M'?l.terms.filter(x=>['Desafíos','Cooperación','Retroalimentación','Recompensas'].includes(x[0])):l.terms.filter(x=>['Misiones','Insignias','Niveles','Puntos'].includes(x[0]));return `${head(`Veta ${k==='D'?'01':k==='M'?'02':'03'} · ${l.name}`,heading,lead)}<div class="concept-grid ${k==='D'?'five':''}">${main.map((x,i)=>`<button class="concept-card" data-action="term" data-level="${k}" data-index="${l.terms.indexOf(x)}"><span class="stone-symbol" aria-hidden="true">${['◇','✧','△','◈','⌁'][i%5]}</span><strong>${esc(x[0])}</strong><span>${esc(x[1])}</span><small>Explorar ejemplo ↗</small></button>`).join('')}</div><div class="actions"><button class="text-button" data-action="catalog" data-id="${k}">Ver el catálogo de ${l.terms.length} ${l.name.toLowerCase()}</button></div>${cite('wh2012')}`;}
  function caseView(){const k=state.level,layer={D:['Sentido de expedición','Una investigación compartida, con vínculos de apoyo y una progresión hacia argumentaciones más sólidas.'],M:['Reglas para contrastar','Cada integrante verifica una fuente; el equipo justifica una conclusión, recibe feedback y la revisa.'],C:['El sistema visible','Una ficha de misión presenta la pregunta y los criterios; un mapa registra las etapas revisadas.']}[k];return `${head('Laboratorio de diseño · caso propio','El Observatorio del Agua','Objetivo: contrastar afirmaciones sobre el agua y justificar una conclusión con evidencias.')}<div class="case-layout"><div><div class="layer-tabs" role="group" aria-label="Capas del caso">${['D','M','C'].map(v=>`<button class="tab ${k===v?'active':''}" aria-pressed="${k===v}" data-action="case-layer" data-id="${v}">${C.levels[v].name}</button>`).join('')}</div><div class="case-panel"><span class="eyebrow">${C.levels[k].name}</span><h3>${layer[0]}</h3><p class="lead">${layer[1]}</p><p class="note">Caso didáctico de autoría. No es un estudio de resultados.</p></div><div class="case-quiz" id="quiz-case">${quiz('case')}</div></div>${seal('coherence')}</div>${cite('wh2012','wh2015')}`;}
  function classify(){const cards=C.cards.slice(state.tray*6,state.tray*6+6),count=state.cards.filter(Boolean).length,correct=C.cards.filter(c=>state.cards[c.id]===c.answer).length;return `${head('Taller en equipos · 16 minutos','Clasificar las vetas','Clasifiquen el objeto o proceso descrito. Justifiquen una duda y contrasten después con la pauta.')}<div class="classification-toolbar"><div class="tray-tabs" role="group" aria-label="Bandejas de tarjetas">${[0,1,2].map(i=>`<button class="tab ${state.tray===i?'active':''}" aria-pressed="${state.tray===i}" data-action="tray" data-index="${i}">Bandeja ${i+1}</button>`).join('')}</div><span id="class-count">${count} / 18 decisiones</span><button class="button small secondary" data-action="class-check">Contrastar con la pauta</button></div><div class="class-grid">${cards.map(c=>`<article class="class-card ${state.classReviewed?(state.cards[c.id]===c.answer?'correct':'revisit'):''}"><label for="card-${c.id}"><span class="card-top">VETA ${String(c.id+1).padStart(2,'0')}</span><strong>${esc(c.title)}</strong><span class="card-context">${esc(c.text)}</span></label><select id="card-${c.id}" data-card="${c.id}" aria-label="Clasificar: ${esc(c.title)}">${[['','Elegir nivel…'],['D','Dinámica'],['M','Mecánica'],['C','Componente'],['?','Quiero discutirlo']].map(([v,label])=>`<option value="${v}" ${state.cards[c.id]===v?'selected':''}>${label}</option>`).join('')}</select>${state.classReviewed?`<div class="card-feedback"><strong>${state.cards[c.id]===c.answer?'Coincide con la pauta':'Revisar en contexto'} · ${C.levels[c.answer].name}</strong><p>${esc(c.why)}</p></div>`:''}</article>`).join('')}</div>${state.classReviewed?`<div class="feedback" id="class-summary" tabindex="-1" role="status">${correct} de 18 decisiones coinciden con la pauta. Revisa las explicaciones y argumenta las dudas; este contraste no es una calificación.</div>`:''}<div class="work-grid"><div>${field('reason','Nuestra duda fundamentada','El caso…, lo clasificamos como… porque… Si cambiara el contexto…')}<p class="note">La justificación abierta se conversa y revisa con el docente.</p></div><div class="class-seal">${seal('classification')}</div></div>${cite('wh2012')}`;}
  function taxView(){const t=C.tax[state.tax];return `${head('Una segunda lente · 21 elementos','¿Qué función cumple el elemento?','Toda y colaboradores organizan los elementos en cinco dimensiones. Úsalas para analizar funciones dentro de un diseño educativo.')}<div class="taxonomy-layout"><div class="taxonomy-tabs" role="group" aria-label="Dimensiones de Toda">${C.tax.map((x,i)=>`<button class="dimension ${state.tax===i?'active':''}" aria-pressed="${state.tax===i}" data-action="tax" data-index="${i}"><span class="dimension-number">0${i+1}</span><span>${esc(x.name)}<small>${x.terms.length} elementos</small></span><span aria-hidden="true">↗</span></button>`).join('')}</div><div class="taxonomy-detail panel"><span class="eyebrow">${esc(t.original)}</span><h3 tabindex="-1" id="tax-heading">${esc(t.question)}</h3><div class="term-chips">${t.terms.map(x=>`<span><strong>${esc(x[0])}</strong><small>${esc(x[1])}</small></span>`).join('')}</div><div class="example"><small>LECTURA DEL CASO · ELABORACIÓN PROPIA</small><p>${esc(t.example)}</p></div></div></div><p class="note">Propuesta original: 2019a. Organización en cinco dimensiones: ampliación 2019b. Traducción y síntesis propias.</p>${cite('toda2019a','toda2019b')}`;}
  const pages=[
    ()=>`<div class="cover-content"><span class="eyebrow">Misión principal 2 · Maestría</span><h1 class="cover-title" id="scene-title" tabindex="-1">Las Vetas<br><span>del Diseño</span></h1><p class="lead">En la Cantera de los Elementos, Maestra Bryn te espera. Aprende a reconocer las piezas y a construir una experiencia con sentido.</p><div class="cover-meta"><span class="small-line"></span><span>Clase sincrónica · 90 min</span><span>Sesión 5 · Módulo 2</span></div><div class="actions"><button class="button" data-action="go" data-page="1">Entrar a la cantera <span aria-hidden="true">→</span></button><button class="button secondary" data-action="guide">Preparar la clase</button></div><p class="note">Avanza junto a quien facilita la sesión. Tus notas se conservan en este dispositivo.</p></div><div class="quarry-caption" aria-hidden="true"><span>CANTERA / 02</span><span>EL DISEÑO EMPIEZA BAJO LA SUPERFICIE</span></div>`,
    ()=>`${head('Maestra Bryn · El encargo','No basta con reunir piedras.','Hay que comprender qué sostiene cada pieza y cómo se relaciona con las demás.')}<div class="mentor">«Una veta valiosa no se reconoce por su brillo. Se reconoce por lo que permite construir.»<small>MAESTRA BRYN · DIÁLOGO CREADO PARA ESTA MISIÓN</small></div><div class="three-column"><article class="panel"><span class="num">01</span><h3>Reconocer</h3><p>Distinguir dinámicas, mecánicas y componentes.</p></article><article class="panel"><span class="num">02</span><h3>Justificar</h3><p>Clasificar elementos y explicar los casos dudosos.</p></article><article class="panel"><span class="num">03</span><h3>Transferir</h3><p>Elegir piezas que apoyen un objetivo de aprendizaje.</p></article></div><p class="note">En vivo: contenido → conversación → mini reto → revisión. El docente anuncia cuándo avanzar.</p>`,
    ()=>`${head('Detonante · decisión individual','¿Más brillo o más sentido?','Elige una opción. Comparte el porqué y vuelve a mirarla después de conversar.')}<div class="split challenge-split"><div id="quiz-initial">${quiz('initial')}</div><aside class="side-note">Una respuesta no cierra la conversación.<br><br>Nos ayuda a decidir qué necesitamos explicar mejor.</aside></div>${cite('wh2015','bw2009')}`,
    ()=>`${head('Veta 01 · arquitectura','Tres niveles. Un mismo diseño.','Explora cada estrato: del sentido de la experiencia a las reglas y sus realizaciones concretas.')}${pyramid()}${cite('wh2012')}`,
    ()=>concept('D','Dinámicas: el sentido del viaje','Dan forma a la experiencia global. Pregúntate qué sentido, vínculos y desarrollo quieres que tenga el recorrido.'),
    ()=>concept('M','Mecánicas: lo que hacemos','Los procesos y las reglas ponen el sistema en marcha. Especifica qué se hace, en qué condiciones y con qué retroalimentación.'),
    ()=>concept('C','Componentes: lo que toma forma','Hacen visible el sistema. Su valor depende de cómo apoyen las acciones y el objetivo, no de cuántos añadamos.'),
    caseView,
    classify,
    ()=>`${head('Conversación de cantera · casos dudosos','Clasificar exige mirar el contexto.','Nombra la unidad de análisis antes de elegir el nivel. Una palabra aislada puede ocultar decisiones diferentes.')}<div class="comparison-wrap"><table class="comparison"><thead><tr><th scope="col">Experiencia o proceso</th><th scope="col">Representación concreta</th></tr></thead><tbody><tr><td><strong>Progresión · dinámica</strong><br>Desarrollo a lo largo del recorrido.</td><td><strong>Barra o nivel · componente</strong><br>Hace visible una parte del avance.</td></tr><tr><td><strong>Competición · mecánica</strong><br>Regla para comparar actuaciones.</td><td><strong>Ranking · componente</strong><br>Muestra posiciones en una tabla.</td></tr><tr><td><strong>Reglas de misiones · mecánica</strong><br>Cómo se encadenan, revisan y reconocen.</td><td><strong>Ficha de misión · componente</strong><br>Un encargo concreto y sus instrucciones.</td></tr></tbody></table></div><div class="mentor compact">¿Cambiaría tu clasificación si cambiara lo que estamos observando?</div>${field('note','Una distinción que quiero recordar','La diferencia entre… y… es…')}${cite('wh2012','toda2019b')}`,
    taxView,
    ()=>`${head('Transferencia · dos marcos','Dos lentes. Una decisión informada.','DMC: ¿a qué nivel pertenece? Toda: ¿qué función cumple? Ninguna lista sustituye la justificación del diseño.')}<div class="split challenge-split"><div id="quiz-bridge">${quiz('bridge')}</div>${seal('transfer')}</div>${cite('wh2012','toda2019b')}`,
    ()=>`${head('Micro desafío individual · 8 minutos','La prueba de Maestría','Revisa cinco decisiones y traduce lo aprendido a una clase propia. Puedes corregir y volver a intentar.')}<div class="micro-layout"><div id="quiz-micro">${quiz('micro')}</div><div class="panel transfer-panel"><span class="eyebrow">Salida · una propuesta propia</span><h3>Del elemento al aprendizaje</h3><p>Describe un objetivo, una dinámica, una mecánica y un componente. Añade qué evidencia observarías.</p>${field('transfer','Mi propuesta','Objetivo:…\nDinámica:…\nMecánica / regla:…\nComponente:…\nEvidencia de aprendizaje:…')}<p class="note">Pauta para revisar: ¿la acción permite observar el objetivo? ¿el componente apoya esa acción? Esta respuesta la revisa el docente.</p></div></div>${cite('wh2012','toda2019b','bw2009')}`,
    ()=>`${head('Misión principal 2 · cierre de la clase','Una veta lista para tallar.','Ahora puedes distinguir las piezas, justificar su clasificación y escogerlas con un propósito.')}<div class="final-seals">${Object.keys(lockNames).map(k=>`<div class="final-seal ${sealStatus(k)}"><strong>${lockNames[k]}</strong><small>${sealStatus(k)==='solved'?'Práctica resuelta':sealStatus(k)==='assisted'?'Apertura acompañada':'Práctica por revisar'}</small></div>`).join('')}</div><div class="split"><div class="panel"><span class="eyebrow">Tu evidencia de la sesión</span><h3>${reviewed('micro')} / 5 decisiones revisadas</h3><p>${state.transfer.trim()?'Tienes una propuesta escrita para conversar con el docente.':'Añade una propuesta en la pantalla 13 para cerrar la transferencia.'}</p><div class="actions"><button class="button" data-action="download">Descargar mi registro</button><button class="button secondary" data-action="notebook">Revisar cuaderno</button></div><p class="note">El registro se guarda localmente; compártelo por el canal que indique tu docente.</p></div><div class="steps"><div class="step"><span class="num">→</span><div><strong>El Tallado de Mecánicas</strong><p>Siguiente misión optativa del módulo 2.</p></div></div><div class="step"><span class="num">◇</span><div><strong>La Gema Motivacional</strong><p>Después, el cierre del módulo y el Fragmento II del Orbe.</p></div></div><p class="note">${CFG.closingFormUrl?`<a href="${esc(CFG.closingFormUrl)}" target="_blank" rel="noopener noreferrer">Abrir formulario de cierre</a>`:'El docente compartirá el formulario de cierre y el código real de esta misión.'}</p></div></div>`
  ];
  function headerStatus(){
    $('#seal-status').innerHTML=Object.keys(lockNames).map((k,i)=>`<button class="seal-dot ${sealStatus(k)}" data-action="seal-info" data-id="${k}" aria-label="Veta ${i+1}: ${lockNames[k]}, ${sealStatus(k)==='solved'?'resuelta':sealStatus(k)==='assisted'?'acompañada':'por revisar'}" title="${lockNames[k]}">${i+1}</button>`).join('');
  }
  function render(focus=false){
    document.body.classList.toggle('is-cover',state.page===0);
    $('#stage').innerHTML=`<section class="scene"><div class="scene-content wide">${pages[state.page]()}</div></section>`;
    $('#page-count').textContent=`${String(state.page+1).padStart(2,'0')} / 14`;
    $('#route-dots').innerHTML=C.pages.map((p,i)=>`<button class="route-dot ${state.visited.includes(i)?'visited':''} ${state.page===i?'current':''}" data-action="go" data-page="${i}" aria-label="Pantalla ${i+1}: ${esc(p.title)}" ${state.page===i?'aria-current="step"':''} title="${esc(p.title)}"></button>`).join('');
    $('#previous').disabled=state.page===0;$('#next-label').textContent=state.page===13?'Cuaderno':'Siguiente';headerStatus();
    if(focus) $('#scene-title').focus({preventScroll:true});
  }
  function navigate(i){
    pauseTimer();state.page=clamp(i,13);state.visited=[...new Set([...state.visited,state.page])];save();
    const hash='#pantalla-'+(state.page+1);if(location.hash!==hash)history.replaceState(null,'',hash);
    render(true);window.scrollTo({top:0,behavior:'instant'});
  }
  function hashPage(){const m=location.hash.match(/^#pantalla-(\d+)$/);if(m){const n=Number(m[1]);if(n>=1&&n<=14)state.page=n-1;}}
  hashPage();state.visited=[...new Set([...state.visited,state.page])];
  let toastTimeout;
  function toast(msg){clearTimeout(toastTimeout);$('#toast').textContent=msg;$('#toast').hidden=false;toastTimeout=setTimeout(()=>$('#toast').hidden=true,4500);}
  function open(title,body){pauseTimer();$('#modal-body').innerHTML=`<h2 id="modal-title" tabindex="-1">${title}</h2>${body}`;if(!$('#modal').open)$('#modal').showModal();$('#modal-title').focus();}
  function close(){pauseTimer();$('#modal').close();}
  function sourceBody(id){const s=C.sources[id];return `<article class="source-entry"><h3>${esc(s.title)}</h3><p class="bibliography">${esc(s.apa)}</p><p>${esc(s.use)}</p><p class="note">${esc(s.limit)}</p>${s.license?`<p class="note">${esc(s.license)}</p>`:''}<p><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.link} ↗</a></p></article>`;}
  function map(){open('El recorrido de la clase',`<p class="muted">90 minutos sugeridos. Sigue la pantalla que anuncie tu docente; el índice permite volver a cualquier contenido.</p><div class="modal-grid">${C.pages.map((p,i)=>`<button class="map-item ${i===state.page?'current':''}" data-action="map-go" data-page="${i}"><span>${String(i+1).padStart(2,'0')}</span>${esc(p.title)} <small>· ${p.time} min</small></button>`).join('')}</div><p class="note">La barra de navegación muestra pantallas visitadas, no dominio del contenido.</p>`);}
  let timer=null,timerPage=-1,timerRemaining=0,timerEnd=0;
  function pauseTimer(){if(timer){timerRemaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));clearInterval(timer);timer=null;}}
  function timerText(){return String(Math.floor(timerRemaining/60)).padStart(2,'0')+':'+String(timerRemaining%60).padStart(2,'0');}
  function timerUI(){const el=$('#teacher-time');if(el)el.textContent=timerText();const btn=$('[data-action="timer-toggle"]');if(btn)btn.textContent=timer?'Pausar':'Iniciar';}
  function guide(){const p=C.pages[state.page];if(timerPage!==state.page){timerPage=state.page;timerRemaining=p.time*60;}
    open('Guía docente · '+String(state.page+1).padStart(2,'0'),`<span class="pill">${p.time} minutos sugeridos · clase sincrónica</span><h3>${esc(p.title)}</h3><p>${esc(p.prompt)}</p><h3>Producto esperado</h3><p>${esc(p.product)}</p><h3>Cómo responder a las dudas</h3><p>${esc(p.adjust)}</p><div class="teacher-timer"><div><span class="eyebrow">Temporizador opcional</span><span id="teacher-time" class="timer" role="timer" aria-live="off">${timerText()}</span></div><div><div class="actions"><button class="button small" data-action="timer-toggle">Iniciar</button><button class="button secondary small" data-action="timer-reset">Reiniciar</button></div><p class="note">No avanza pantallas ni penaliza. Al cerrar la guía, se pausa.</p></div></div><details><summary>Preparación y registro</summary><p class="note">La tesis prevé 45 minutos de lectura autónoma previa. Comparte el material antes de la sesión. Prepara el canal para recoger los registros y el formulario de cierre si lo utilizas. El HTML no sincroniza dispositivos ni envía respuestas automáticamente.</p><p class="note">Las pistas y pautas bajo candado son apoyo complementario. Los contenidos y la navegación permanecen accesibles. Las respuestas abiertas se revisan con criterio docente.</p>${cite('bw2009')}</details>`);}
  function sealOpen(id){const s=sealTexts[id];open(s[0],`<div class="seal-reading"><span class="stone-symbol">◇</span><p>${s[1]}</p></div><p class="note">${sealStatus(id)==='solved'?'Pauta abierta tras revisar la práctica.':'Pauta abierta con acompañamiento. Puedes continuar revisando la práctica.'}</p>${cite(id==='transfer'?'toda2019b':'wh2012')}`);}
  function record(){
    const lines=['BUSCADORES DE LA GAMIFICACIÓN PERDIDA','Las Vetas del Diseño · Misión principal 2','Registro de práctica local · no es una calificación','',`Equipo / alias (opcional): ${state.team||'Sin registrar'}`,''];
    Object.entries(C.quizzes).forEach(([g,qs])=>{lines.push({initial:'DETONANTE',case:'OBSERVATORIO DEL AGUA',bridge:'DOS LENTES',micro:'MICRO DESAFÍO'}[g]);qs.forEach((q,i)=>{const s=qState(g,i);lines.push(`${i+1}. ${q.q}`,`Decisión: ${s.selected===null?'Sin responder':q.options[s.selected]}`,`Revisión: ${s.checked===null?'Pendiente':s.checked===q.answer?'Coincide con la pauta':'Por revisar'}`,s.checked!==null?`Retroalimentación: ${q.why}`:'','');});});
    lines.push('CLASIFICACIÓN EN EQUIPO');C.cards.forEach(c=>lines.push(`${c.id+1}. ${c.title}: ${state.cards[c.id]==='?'?'Quiero discutirlo':C.levels[state.cards[c.id]]?.name||'Sin clasificar'}${state.classReviewed?' · pauta: '+C.levels[c.answer].name:''}`));
    lines.push('','JUSTIFICACIÓN DEL EQUIPO',state.reason||'Pendiente','','DISTINCIÓN QUE QUIERO RECORDAR',state.note||'Pendiente','','TRANSFERENCIA A MI CLASE',state.transfer||'Pendiente','','SELLOS DE PRÁCTICA');Object.keys(lockNames).forEach(k=>lines.push(`${lockNames[k]}: ${sealStatus(k)==='solved'?'resuelta':sealStatus(k)==='assisted'?'apertura acompañada':'por revisar'}`));
    lines.push('','Las respuestas abiertas requieren revisión docente. Compártelo por el canal de tu clase.','El código oficial lo proporciona el docente mediante el cierre de la misión.');return lines.join('\n');
  }
  function download(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([record()],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='Mi_registro_Las_Vetas_del_Diseno.txt';a.hidden=true;document.body.append(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(url);},10000);toast('Descarga solicitada. También puedes ver y copiar el registro en pantalla.');}
  function viewRecord(){open('Mi registro completo',`<p class="muted">Selecciona y copia el texto para compartirlo por el canal de tu clase. Incluye tus decisiones, revisiones y respuestas abiertas.</p><label class="field">Registro completo<textarea readonly rows="16" style="min-height:350px;font-size:13px">${esc(record())}</textarea></label><div class="actions"><button class="button" data-action="download">Descargar TXT</button><button class="button secondary" data-action="notebook">Volver al cuaderno</button></div>`);}
  function notebook(){open('Cuaderno de Maestría',`<p class="muted">Tu práctica y tus notas en este dispositivo. ${persistent?'El borrador se conserva al volver con el mismo navegador.':'El navegador no permite conservar el borrador: descarga o copia el registro antes de salir.'}</p><label class="field">Equipo o alias (opcional)<input type="text" data-field="team" maxlength="100" value="${esc(state.team)}" placeholder="Puedes dejarlo vacío"></label><div class="notebook-stats">${Object.keys(lockNames).map(k=>`<span>${lockNames[k]}<strong>${sealStatus(k)==='solved'?'Resuelta':sealStatus(k)==='assisted'?'Acompañada':'Por revisar'}</strong></span>`).join('')}</div>${field('reason','Duda fundamentada del equipo')}${field('note','Distinción que quiero recordar')}${field('transfer','Mi propuesta para una clase')}<div class="actions"><button class="button" data-action="download">Descargar registro completo</button><button class="button secondary" data-action="view-record">Ver registro</button><button class="text-button" data-action="copy">Copiar registro</button></div><p class="note">Estos datos no se envían automáticamente. El docente recoge el registro por su canal de clase.</p><details><summary>Empezar una nueva práctica</summary><p class="note">Borra únicamente el borrador de Las Vetas del Diseño en este navegador.</p><button class="button secondary small" data-action="reset-confirm">Reiniciar esta misión</button></details>`);}
  function updateQuiz(g,focus){const wrap=$('#quiz-'+g);if(wrap){wrap.innerHTML=quiz(g);if(focus)$(`#question-${g}`).focus({preventScroll:true});}headerStatus();const id=g==='case'?'coherence':g==='bridge'?'transfer':null;if(id){const lock=$('#stage .lock-panel');if(lock)lock.outerHTML=seal(id);}}
  document.addEventListener('input',e=>{const key=e.target.dataset.field;if(['team','reason','note','transfer'].includes(key)){state[key]=e.target.value.slice(0,key==='team'?100:10000);save();}});
  document.addEventListener('change',e=>{if(e.target.dataset.card!==undefined){const i=Number(e.target.dataset.card);if(i>=0&&i<18){state.cards[i]=e.target.value;state.classReviewed=false;save();$('#class-count').textContent=`${state.cards.filter(Boolean).length} / 18 decisiones`;document.querySelectorAll('.card-feedback').forEach(n=>n.remove());document.querySelectorAll('.class-card').forEach(n=>n.classList.remove('correct','revisit'));$('#class-summary')?.remove();$('.class-seal').innerHTML=seal('classification');headerStatus();}}});
  document.addEventListener('click',async e=>{
    const b=e.target.closest('[data-action]');if(!b||b.disabled)return;
    const a=b.dataset.action,id=b.dataset.id,g=b.dataset.group;
    if(a==='go')navigate(Number(b.dataset.page));
    else if(a==='map-go'){close();navigate(Number(b.dataset.page));}
    else if(a==='map')map();else if(a==='close')close();else if(a==='guide')guide();
    else if(a==='sources')open('Fuentes y criterios de diseño',`<p class="muted">Bibliografía del contenido y del diseño formativo. Los ejemplos, diálogos y pautas de esta misión son de elaboración propia.</p>${Object.keys(C.sources).map(sourceBody).join('')}<p class="note">Adaptación de la ficha de sesión 5 de la tesis de Nicolás Espinoza. La narrativa respeta Ludaria, Maestra Bryn y el atributo Maestría. La ilustración de la cantera se ha generado para esta propuesta.</p>`);
    else if(a==='source')open(C.sources[id].short,sourceBody(id));
    else if(a==='notebook')notebook();
    else if(a==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('La incrustación no permite pantalla completa. Abre el enlace de la misión en una pestaña.');}}
    else if(a==='level'){state.level=id;save();render();$('#layer-heading').focus({preventScroll:true});}
    else if(a==='case-layer'){state.level=id;save();render();}
    else if(a==='term'){const l=C.levels[b.dataset.level],t=l.terms[Number(b.dataset.index)];open(t[0],`<span class="pill">${l.name} · Werbach y Hunter</span><p>${esc(t[1])}</p><div class="example"><small>EJEMPLO PROPIO</small><p>${esc(t[2])}</p></div>${cite('wh2012')}`);}
    else if(a==='catalog'){const l=C.levels[id];open('Catálogo · '+l.name,`<p class="muted">Paleta de referencia: selecciona según el propósito; no es una lista que debas completar.</p><div class="catalog-list">${l.terms.map(t=>`<article><h3>${esc(t[0])}</h3><p>${esc(t[1])}</p><p class="note">Ejemplo propio: ${esc(t[2])}</p></article>`).join('')}</div>${cite('wh2012')}`);}
    else if(a==='choose'){const i=state.qIndex[g]||0,s=qState(g,i);s.selected=Number(b.dataset.index);s.checked=null;save();updateQuiz(g,false);$(`[data-quiz="${g}"] [data-index="${s.selected}"]`).focus({preventScroll:true});}
    else if(a==='check'){const s=qState(g,state.qIndex[g]||0);if(s.selected===null)return;s.checked=s.selected;save();updateQuiz(g,false);$(`[data-quiz="${g}"] .feedback:not(.hint)`)?.scrollIntoView({block:'nearest',behavior:'smooth'});}
    else if(a==='hint'){state.hints[g+'-'+(state.qIndex[g]||0)]=true;save();updateQuiz(g,false);}
    else if(a==='quiz-next'||a==='quiz-prev'){state.qIndex[g]=clamp((state.qIndex[g]||0)+(a==='quiz-next'?1:-1),C.quizzes[g].length-1);save();updateQuiz(g,true);}
    else if(a==='assist'){if(!state.assisted.includes(id))state.assisted.push(id);save();render();sealOpen(id);}
    else if(a==='seal')sealOpen(id);
    else if(a==='seal-info'){if(sealStatus(id)!=='locked')sealOpen(id);else open('Veta · '+lockNames[id],`<p>Esta pauta complementaria está bajo candado. El reto se encuentra en la pantalla ${id==='coherence'?8:id==='classification'?9:12}.</p><p class="note">Puedes volver al reto o solicitar allí una apertura acompañada. El contenido de la clase sigue accesible.</p>`);}
    else if(a==='tray'){state.tray=clamp(Number(b.dataset.index),2);save();render();$(`[data-action="tray"][data-index="${state.tray}"]`).focus({preventScroll:true});}
    else if(a==='class-check'){state.classReviewed=true;save();render();$('#class-summary').focus({preventScroll:true});}
    else if(a==='tax'){state.tax=clamp(Number(b.dataset.index),4);save();render();$('#tax-heading').focus({preventScroll:true});}
    else if(a==='download')download();
    else if(a==='view-record')viewRecord();
    else if(a==='copy'){try{await Promise.race([navigator.clipboard.writeText(record()),new Promise((_,reject)=>setTimeout(()=>reject(new Error('clipboard unavailable')),4000))]);toast('Registro copiado.');}catch{viewRecord();toast('Selecciona y copia el texto del registro en pantalla.');}}
    else if(a==='reset-confirm')open('¿Empezar de nuevo?',`<p>Se borrarán las decisiones y notas de esta misión en este navegador.</p><div class="actions"><button class="button" data-action="reset">Sí, reiniciar Las Vetas</button><button class="button secondary" data-action="notebook">Conservar mi práctica</button></div>`);
    else if(a==='reset'){close();try{localStorage.removeItem(CFG.storageKey);}catch{}state=initial();navigate(0);toast('Nueva práctica preparada.');}
    else if(a==='timer-toggle'){if(timer)pauseTimer();else{if(timerRemaining<=0)timerRemaining=C.pages[state.page].time*60;timerEnd=Date.now()+timerRemaining*1000;timer=setInterval(()=>{timerRemaining=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));timerUI();if(timerRemaining===0){pauseTimer();timerUI();toast('Tiempo sugerido completado. Puedes continuar según el ritmo de la clase.');}},300);}timerUI();}
    else if(a==='timer-reset'){pauseTimer();timerRemaining=C.pages[state.page].time*60;timerUI();}
  });
  $('#previous').addEventListener('click',()=>navigate(state.page-1));
  $('#next').addEventListener('click',()=>state.page===13?notebook():navigate(state.page+1));
  $('#modal').addEventListener('close',pauseTimer);
  document.addEventListener('keydown',e=>{if($('#modal').open||e.altKey||e.ctrlKey||e.metaKey||e.target.matches('input,textarea,select'))return;if(e.key==='ArrowRight'){e.preventDefault();if(state.page<13)navigate(state.page+1);}if(e.key==='ArrowLeft'){e.preventDefault();if(state.page>0)navigate(state.page-1);}});
  window.addEventListener('hashchange',()=>{hashPage();navigate(state.page);});
  window.addEventListener('beforeunload',save);
  const sparkPositions=[[19,21],[27,74],[36,29],[58,18],[65,61],[77,32],[87,68],[94,24]];
  $('#fireflies').innerHTML=sparkPositions.map(([x,y],i)=>`<span class="fly" style="left:${x}%;top:${y}%;animation-delay:-${i*1.5}s"></span>`).join('');
  render();
})();
